function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const TODAY = '2026-09-09';
const m = {};
let firstSend = null, lastSend = null;

for (const r of rows) {
  const st = s(r.startup);
  if (!st) { continue; }
  if (!m[st]) { m[st] = { startup: st, owner: s(r.owner), pending: 0, sent: 0, dates: {} }; }
  const e = m[st];
  const shared = s(r.deal_shared).toLowerCase() === 'yes';
  const paused = s(r.pause) !== '';
  if (shared) {
    e.sent++;
    const d = s(r.date_shared);
    if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
      e.dates[d] = (e.dates[d] || 0) + 1;
      if (!firstSend || d < firstSend) { firstSend = d; }
      if (!lastSend || d > lastSend) { lastSend = d; }
    }
  } else if (!paused) { e.pending++; }
}

// how many distinct SEND DAYS the programme has actually run
const allDays = {};
for (const k of Object.keys(m)) { for (const d of Object.keys(m[k].dates)) { allDays[d] = true; } }
const sendDays = Object.keys(allDays).length || 1;

const list = Object.keys(m).map(function (k) {
  const e = m[k];
  let tot = 0;
  for (const d of Object.keys(e.dates)) { tot += e.dates[d]; }
  const perDay = tot / sendDays;                       // avg sends per active send-day
  const perWeek = perDay * 5;                          // weekdays only
  const weeks = perWeek > 0 ? e.pending / perWeek : null;
  return { startup: e.startup, owner: e.owner, pending: e.pending, sent: e.sent,
           sends_per_week: Math.round(perWeek * 10) / 10,
           runway_weeks: weeks === null ? null : Math.round(weeks * 10) / 10 };
});

const short = list.filter(function (x) { return x.runway_weeks !== null && x.runway_weeks < 4.3; });
const never = list.filter(function (x) { return x.runway_weeks === null; });
short.sort(function (a, b) { return a.runway_weeks - b.runway_weeks; });
list.sort(function (a, b) { return (a.runway_weeks === null ? 999 : a.runway_weeks) - (b.runway_weeks === null ? 999 : b.runway_weeks); });

return [{ json: {
  send_window: firstSend + ' to ' + lastSend,
  distinct_send_days: sendDays,
  startups: list.length,
  UNDER_ONE_MONTH: short.length,
  never_sent: never.map(function (x) { return x.startup + ' (' + x.pending + ' pending)'; }),
  shortage_list: short,
  all: list
}}];
